mapper.select:
SELECT * FROM ( SELECT b.board_sq AS sq, b.board_ttl AS ttl, u.user_id AS userId, u.user_nm AS userNm, u.user_nickname AS userNickname, b.board_type_cd AS boardTypeCd, b.board_created_at_dtm AS createdAt, b.board_view_cnt AS viewCnt, b.board_comment_cnt AS commentCnt, b.board_recommend_cnt AS recommendCnt, CASE WHEN b.board_type_cd = 1401 THEN NULL ELSE b.board_adopt_status_cd END AS boardAdoptStatusCd, b.board_category_cd AS boardCategoryCd, cc.common_code_nm AS boardCategoryNm, b.board_description_edt AS description, 'BOARD' AS mainType FROM TBL_BOARD_M b JOIN TBL_USER_M u ON b.user_sq = u.user_sq LEFT JOIN TBL_COMMON_CODE_C cc ON cc.common_code_sq = b.board_category_cd WHERE b.board_is_deleted_yn = 'N' AND b.board_type_cd IN (1401, 1402) UNION ALL SELECT a.answer_sq AS sq, a.answer_ttl AS ttl, u.user_id AS userId, u.user_nm AS userNm, u.user_nickname AS userNickname, 1499 AS boardTypeCd, a.answer_created_at_dtm AS createdAt, a.answer_view_cnt AS viewCnt, a.answer_comment_cnt AS commentCnt, a.answer_recommend_cnt AS recommendCnt, CASE WHEN a.answer_is_adopted_yn = 'Y' THEN 1502 ELSE 1504 END AS boardAdoptStatusCd, NULL AS boardCategoryCd, NULL AS boardCategoryNm, a.answer_description_edt AS description, 'ANSWER' AS mainType FROM TBL_BOARD_ANSWER_S a JOIN TBL_USER_M u ON a.user_sq = u.user_sq
JOIN TBL_BOARD_M pb ON pb.board_sq = a.board_sq AND pb.board_type_cd IN (1401, 1402) WHERE a.answer_is_deleted_yn = 'N' ) AS unified WHERE 1=1 AND boardTypeCd IN #{t}
ORDER BY boardTypeCd ttl
userId userNm userNickname boardAdoptStatusCd boardCategoryCd viewCnt recommendCnt createdAt ${sortOrder} LIMIT #{size} OFFSET #{offset}

SELECT comment_sq AS commentSq, board_sq AS boardSq, user_sq AS userSq,
comment_description_txt AS commentDescriptionTxt FROM TBL_BOARD_COMMENT_S WHERE comment_sq =
#{commentSq}
